<?php
declare(strict_types=1);
session_start();
if (empty($_SESSION['usuario_id']) || ($_SESSION['rol']??'')!=='empleado') {http_response_code(403);exit('Acceso exclusivo para empleados.');}
function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
require __DIR__.'/../config/conexion_azucreativo.php';
$desde=$_GET['desde']??date('Y-m-d',strtotime('-30 days'));
$hasta=$_GET['hasta']??date('Y-m-d');
if (!preg_match('/^\d{4}-\d{2}-\d{2}$/',$desde)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$hasta)) {http_response_code(400);exit('Fechas inválidas.');}
$ventas=[];$error='';
try {
 $q=$pdo->prepare("SELECT v.ID_Venta,v.Fecha_Venta,v.Metodo_Pago,v.Estado_Venta,v.Total,CASE WHEN w.ID_Venta IS NOT NULL THEN 'Registrado' ELSE 'Invitado' END AS Origen,CASE WHEN w.ID_Venta IS NOT NULL THEN CONCAT_WS(' ',NULLIF(c.Nombre,''),NULLIF(c.Apellido,'')) ELSE 'Cliente invitado' END AS Cliente FROM Venta v JOIN Cliente c ON c.ID_Cliente=v.ID_Cliente LEFT JOIN Venta_Cliente_Web w ON w.ID_Venta=v.ID_Venta WHERE v.Fecha_Venta>=? AND v.Fecha_Venta<DATE_ADD(?,INTERVAL 1 DAY) AND (w.ID_Venta IS NOT NULL OR (c.Nombre='Cliente' AND c.Apellido='Invitado')) ORDER BY v.ID_Venta DESC LIMIT 500");
 $q->execute([$desde,$hasta]);$ventas=$q->fetchAll(PDO::FETCH_ASSOC);
} catch(Throwable $e){error_log('Pedidos de clientes: '.$e->getMessage());$error='No fue posible consultar las compras. Comprueba la tabla Venta_Cliente_Web y la conexión a MySQL.';}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pedidos de clientes | Azucreativo</title><link rel="stylesheet" href="../styles.css"><link rel="stylesheet" href="../config/menu-horizontal.css"><link rel="stylesheet" href="../config/roles-pos.css"><link rel="stylesheet" href="/Azucreativo/config/scroll-final.css?v=3"><link rel="stylesheet" href="/Azucreativo/config/avisos-legibles.css?v=20261122"><script src="/Azucreativo/config/menu-plegable.js" defer></script><style>.pedidos-tabla{width:100%;border-collapse:collapse;background:white;color:#172b4d}.pedidos-tabla th,.pedidos-tabla td{padding:12px;border-bottom:1px solid #dbe7f3;text-align:left}.pedidos-tabla th{background:#e9f3ff}.pedidos-wrap{overflow-x:auto}.pedidos-filtro{display:flex;flex-wrap:wrap;gap:12px;align-items:end;margin:15px 0}.pedidos-filtro label{display:grid;gap:4px}.pedidos-link{display:inline-block;padding:7px 12px;background:#294c6a;color:white;border-radius:8px;text-decoration:none}.pedidos-nota{color:#294c6a}</style>
<link rel="stylesheet" href="/Azucreativo/config/mobile-responsive.css?v=20261122logout2">
<script src="/Azucreativo/config/mobile-responsive.js?v=20261122" defer></script>
</head><body><div class="app-container"><aside class="sidebar"><nav class="sidebar-nav role-nav"><img class="role-logo" src="../img/logo-azucreativo.jpeg" alt="Logo"><span class="brand-name" style="color:#294c6a!important;-webkit-text-fill-color:#294c6a!important">AZUCREATIVO</span><a href="index.php">🛒 Ventas y catálogo</a><a href="../admin/usuarios.php">👥 Registrar cliente</a><a href="corte.php">💰 Corte de caja</a><a class="active" href="pedidos.php">📦 Pedidos de clientes</a></nav></aside><main class="main-content"><header class="header-bar"><div class="header-left"><h1 class="view-title">Pedidos de clientes · Por ticket</h1></div><div class="header-user"><span>Hola, <?=h($_SESSION['usuario']??'Empleado')?></span><a href="../login/logout.php" class="btn-logout">Cerrar sesión</a></div></header><div class="view-container"><div class="card"><h2>Compras realizadas en línea</h2><p class="pedidos-nota">Incluye compras de clientes registrados e invitados, ordenadas por folio de ticket. Son ventas ya registradas: no vuelvas a cobrarlas ni a descontar inventario.</p><form class="pedidos-filtro" method="get"><label>Desde<input type="date" name="desde" value="<?=h($desde)?>" required></label><label>Hasta<input type="date" name="hasta" value="<?=h($hasta)?>" required></label><button class="pos-action" type="submit">Consultar</button></form><?php if($error):?><p role="alert" style="color:#111;background:#ffe7e7;padding:12px"><?=h($error)?></p><?php elseif(!$ventas):?><p>No hay compras registradas para este periodo.</p><?php else:?><p><strong><?=count($ventas)?></strong> tickets encontrados (máximo 500 por consulta).</p><div class="pedidos-wrap"><table class="pedidos-tabla"><thead><tr><th>Ticket</th><th>Fecha</th><th>Tipo de cliente</th><th>Cliente</th><th>Pago</th><th>Estado</th><th>Total</th><th>Comprobante</th></tr></thead><tbody><?php foreach($ventas as $v):?><tr><td>#<?=h($v['ID_Venta'])?></td><td><?=h($v['Fecha_Venta'])?></td><td><?=h($v['Origen'])?></td><td><?=h($v['Cliente'])?></td><td><?=h($v['Metodo_Pago'])?></td><td><?=h($v['Estado_Venta'])?></td><td>$<?=number_format((float)$v['Total'],2)?></td><td><a class="pedidos-link" href="../ticket.php?id=<?=urlencode((string)$v['ID_Venta'])?>" target="_blank" rel="noopener">Ver ticket</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div></main></div></body></html>